def parse_time(text):
    text = text.strip()
    period = text[-2:]
    hour, minute = map(int, text[:-2].split(":"))
    if period == "AM":
        if hour == 12:
            hour = 0
    else:
        if hour != 12:
            hour += 12
    return hour * 60 + minute

